import styled from '@emotion/styled';

type ContainerGap = 8 | 16;

interface StyledContainerProps {
  $gap?: ContainerGap;
}

export const StyledContainer = styled.div<StyledContainerProps>(({ $gap }) => ({
  display: 'flex',
  width: '100%',
  '& > *': {
    flex: '1 1 0',
    minWidth: '0 !important',
    maxWidth: 'none !important',
  },
  ...($gap === 8 && { gap: '8px' }),
  ...($gap === 16 && { gap: '16px' }),
}));
